// security.js — comprehensive security middleware
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import cors from 'cors';
import { body, validationResult } from 'express-validator';
import hpp from 'hpp';
import xss from 'xss-clean';

export function applySecurity(app) {
  // Security headers (helmet)
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'", "'unsafe-inline'"],
        styleSrc: ["'self'", "'unsafe-inline'", "https://fonts.googleapis.com"],
        imgSrc: ["'self'", "data:", "https://images.example.com"],
        connectSrc: ["'self'", "https://api.example.com"],
        fontSrc: ["'self'", "https://fonts.gstatic.com"],
        objectSrc: ["'none'"],
        frameAncestors: ["'none'"]
      }
    },
    crossOriginEmbedderPolicy: true,
    crossOriginOpenerPolicy: true,
    crossOriginResourcePolicy: { policy: "same-site" },
    dnsPrefetchControl: true,
    frameguard: { action: "deny" },
    hidePoweredBy: true,
    hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
    ieNoOpen: true,
    noSniff: true,
    referrerPolicy: { policy: "strict-origin-when-cross-origin" },
    xssFilter: true
  }));

  // CORS (restrict origins in production)
  app.use(cors({
    origin: process.env.CLIENT_URL || 'http://localhost:3000',
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization']
  }));

  // Rate limiting
  app.use('/api', rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false
  }));

  // Prevent HTTP Parameter Pollution
  app.use(hpp());

  // XSS cleaning
  app.use(xss());
}

// Input validation middleware
export const validateRequest = (validations) => async (req, res, next) => {
  await Promise.all(validations.map(v => v.run(req)));
  const errors = validationResult(req);

  if (errors.isEmpty()) return next();

  const err = new Error('Validation failed');
  err.statusCode = 400;
  err.errors = errors.array().map(e => ({
    field: e.path,
    message: e.msg,
    value: e.value
  }));
  next(err);
};

// SQL injection prevention — always use parameterised queries
// GOOD: pool.execute('SELECT * FROM users WHERE id = ?', [id])
// BAD:  pool.query(`SELECT * FROM users WHERE id = ${id}`)

// NoSQL injection prevention
